import { supabase } from './supabase';

export interface UploadProgressCallback {
  (progressPercent: number): void;
}

const WORKER_URL = import.meta.env.VITE_IMAGE_WORKER_URL || '';

/**
 * Uploads product image directly to Cloudflare R2 using a presigned upload URL
 * generated by our secure Cloudflare Worker.
 * If Cloudflare Worker is not configured, provides a seamless Supabase Storage or local fallback.
 */
export async function uploadProductImage(
  file: File,
  onProgress?: UploadProgressCallback
): Promise<string> {
  // Validate file type
  const validTypes = ['image/jpeg', 'image/png', 'image/webp'];
  if (!validTypes.includes(file.type)) {
    throw new Error('Invalid image type. Please select a JPG, PNG, or WebP image.');
  }

  // Validate file size (max 5MB)
  const maxSize = 5 * 1024 * 1024;
  if (file.size > maxSize) {
    throw new Error('Image size exceeds 5MB limit. Please compress or select a smaller image.');
  }

  // Get current user session
  const { data: { session } } = await supabase.auth.getSession();
  const token = session?.access_token;

  // 1. If Cloudflare Worker URL is available and configured
  if (WORKER_URL && token) {
    try {
      if (onProgress) onProgress(15);

      const res = await fetch(`${WORKER_URL.replace(/\/+$/, '')}/api/upload-url`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({
          fileName: file.name,
          contentType: file.type,
        }),
      });

      if (!res.ok) {
        const errorData = await res.json().catch(() => ({}));
        throw new Error(errorData.error || `Worker returned HTTP ${res.status}`);
      }

      const { uploadUrl, publicUrl } = await res.json();
      if (onProgress) onProgress(45);

      // Perform S3 presigned PUT directly to Cloudflare R2
      const uploadRes = await fetch(uploadUrl, {
        method: 'PUT',
        headers: {
          'Content-Type': file.type,
        },
        body: file,
      });

      if (!uploadRes.ok) {
        throw new Error(`Failed to upload to Cloudflare R2 (HTTP ${uploadRes.status})`);
      }

      if (onProgress) onProgress(100);
      return publicUrl;
    } catch (err) {
      console.warn('Cloudflare Worker upload failed, attempting storage fallback:', err);
      // Fall through to fallback
    }
  }

  // 2. Fallback: Supabase Storage bucket 'product-images' (if enabled)
  try {
    if (onProgress) onProgress(30);
    const fileExt = file.name.split('.').pop() || 'webp';
    const filePath = `products/${Date.now()}-${Math.random().toString(36).substring(2, 7)}.${fileExt}`;

    const { error: uploadError } = await supabase.storage
      .from('product-images')
      .upload(filePath, file, { cacheControl: '3600', upsert: true });

    if (!uploadError) {
      const { data } = supabase.storage.from('product-images').getPublicUrl(filePath);
      if (onProgress) onProgress(100);
      return data.publicUrl;
    }
  } catch (err) {
    console.warn('Supabase storage fallback failed:', err);
  }

  // 3. Fallback: Upload to local server /api/upload
  try {
    const base64Data: string = await new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = () => resolve(reader.result as string);
      reader.onerror = reject;
      reader.readAsDataURL(file);
    });

    const localUploadRes = await fetch('http://localhost:5001/api/upload', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ base64: base64Data, filename: file.name }),
    });

    if (localUploadRes.ok) {
      const uploadJson = await localUploadRes.json();
      if (onProgress) onProgress(100);
      return uploadJson.public_url;
    }
  } catch (err) {
    console.warn('Local server upload fallback failed:', err);
  }

  // 4. Ultimate Fallback: Return Base64 Data URL
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => {
      if (onProgress) onProgress(100);
      resolve(reader.result as string);
    };
    reader.onerror = (error) => reject(error);
    reader.readAsDataURL(file);
  });
}
